%[text] %[text:anchor:T_D48C173C] # High Voltage Battery - Simulation Case
%[text] %[text:anchor:H_1B376934] ## Random current
model_name = "testModel_BatteryHV";
load_system(model_name)

BatteryHV_SystemTable_params

set_param(model_name + "/High Voltage Battery", ReferencedSubsystem = "BatteryHV_SystemTable_refsub");

set_param(model_name + "/Inputs", ReferencedSubsystem = "BatteryHV_Inputs_Random_refsub");
%%
%[text] Test conditions
signal_design_matrix = SignalTool2.generateSignalDesignMatrixFromTraceProperties(...
  RandomSeed = 12, ...
  FInitialValue = 0, ...
  XInitialFlatLength = 5, ...
  XInitialTransitionLength = 5, ...
  NumTransitions = 20, ...
  TransitionXRange = [10 30], ...
  FlatXRange = [120 240], ...
  FRange = [-10 50], ...
  XFinalTransitionLength = 30, ...
  XFinalFlatLength = 100, ...
  FFinalValue = 0 );

data_table = SignalTool2.getXYVectorsFromSignalDesignMatrix(signal_design_matrix);

t = data_table.X;
f = data_table.Y;

fig = figure; %[output:6906c7dc]
fig.Position(3:4) = [900 300];  % width height %[output:6906c7dc]
SignalTool2.plotLookupTable1D(t, f, InterpolationInterval=0.5, ParentAxes=axes(fig)) %[output:6906c7dc]
%%
set_param(model_name + "/Inputs/Load current", "Table", CodeTool1.stringify(f))
set_param(model_name + "/Inputs/Load current", "BreakpointsForDimension1", CodeTool1.stringify(t))
%[text] Initial conditions
initial.hvBattery_SOC_pct = 50;
initial.hvBattery_SOC_normalized = initial.hvBattery_SOC_pct / 100;

tmp_batt_charge = HighVoltageBatteryTool1.getAmpereHourRating( ...
  Capacity = simscape.Value(batteryHV.nominalCapacity_kWh, "kWh"), ...
  Voltage = simscape.Value(batteryHV.nominalVoltage_V, "V"), ...
  StateOfCharge = initial.hvBattery_SOC_normalized );

initial.hvBattery_Charge_Ahr = value(tmp_batt_charge, "Ah");
disp(initial) %[output:39254310]
%[text] Simulation
sim_in = Simulink.SimulationInput(model_name);
sim_in = setModelParameter(sim_in, StopTime = string(t(end)));

sim_out = sim(sim_in);

logged_signals = extractTimetable(sim_out.logsout);

BatteryHV_ResultsPlot(Timetable = logged_signals); %[output:7ac525a2]
